const request = require('supertest');
const app = require('./app');

describe('POST /users – input validation', () => {
  // ── 400 cases ──────────────────────────────────────────────────────────────

  test('rejects request with no body at all (400)', async () => {
    const res = await request(app)
      .post('/users')
      .set('Content-Type', 'application/json')
      .send('');                          // truly empty body

    expect(res.statusCode).toBe(400);
    expect(res.body.error).toMatch(/missing required field: name/i);
  });

  test('rejects request whose body omits the name field (400)', async () => {
    const res = await request(app)
      .post('/users')
      .send({ email: 'noname@example.com' });

    expect(res.statusCode).toBe(400);
    expect(res.body.error).toMatch(/missing required field: name/i);
  });

  test('rejects request where name is null (400)', async () => {
    const res = await request(app)
