const express = require('express');

const app = express();
app.use(express.json());

app.post('/users', (req, res) => {
  const { name } = req.body;

  // Reject if `name` is missing or not a string
  if (name === undefined || name === null) {
    return res.status(400).json({ error: '`name` is required.' });
  }
  if (typeof name !== 'string') {
    return res.status(400).json({ error: '`name` must be a string.' });
  }
  if (name.trim() === '') {
    return res.status(400).json({ error: '`name` must not be blank.' });
  }

  // Happy-path — proceed with the validated name
  return res.status(201).json({ message: 'User created.', name: name.trim() });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));

module.exports = app; // exported for testing

{
  "name": "express-validation-demo",
  "version": "1.0.0",
  "description": "Basic Express app with input validation",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "test": "jest --verbose"
  },
  "dependencies": {
    "express": "^4.18.2"
  },
  "devDependencies": {
    "jest": "^29.7.0",
    "supertest": "^6.3.4"
  }
}

const request = require('supertest');
const app     = require('./app');

describe('POST /users — name validation', () => {
  // ── 400 cases ────────────────────────────────────────────────────────────

  test('returns 400 when body is empty (name missing)', async () => {
    const res = await request(app).post('/users').send({});
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/required/i);
  });

  test('returns 400 when name is null', async () => {
    const res = await request(app).post('/users').send({ name: null });
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/required/i);
  });

  test('returns 400 when name is a number', async () => {
    const res = await request(app).post('/users').send({ name: 42 });
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/string/i);
  });

  test('returns 400 when name is a boolean', async () => {
    const res = await request(app).post('/users').send({ name: true });
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/string/i);
  });

  test('returns 400 when name is an array', async () => {
    const res = await request(app).post('/users').send({ name: ['Alice'] });
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/string/i);
  });

  test('returns 400 when name is an object', async () => {
    const res = await request(app).post('/users').send({ name: { value: 'Alice' } });
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/string/i);
  });

  test('returns 400 when name is a blank string', async () => {
    const res = await request(app).post('/users').send({ name: '   ' });
    expect(res.status).toBe(400);
    expect(res.body.error).toMatch(/blank/i);
  });

  // ── 201 cases ────────────────────────────────────────────────────────────

  test('returns 201 with a valid name', async () => {
    const res = await request(app)
      .post('/users')
      .send({ name: 'Alice' });
    expect(res.status).toBe(201);
    expect(res.body.name).toBe('Alice');
  });

  test('trims whitespace from a valid name', async () => {
    const res = await request(app)
      .post('/users')
      .send({ name: '  Bob  ' });
    expect(res.status).toBe(201);
    expect(res.body.name).toBe('Bob');
  });
});

